#define TACTICS_COORDINATION_MODEL_ONLY
#include "coordination.h"
#include <cstdio>
#include <cstdlib>
using namespace tactics;static int checks=0;static void yes(bool v,const char*s){++checks;if(!v){std::fprintf(stderr,"FAIL %s\n",s);std::exit(1);}}
static CampRollout quote(int ticks,double shield=100,double camp_hp=150){Actor a;a.id=0;a.type=10;a.pos={0,0};a.hp=300;a.max_hp=1000;a.strength=50;a.range=1;a.alive=a.can_attack=a.can_cast=true;a.shield=shield;a.shield_ticks=ticks;CampClearBody b;b.actor=a;b.alternative_known=true;Camp c;c.id=2;c.pos={1,0};c.hp=c.max_hp=camp_hp;c.strength=50;c.range=3;return rollout_camp_clear(std::span(&b,1),std::array{CampClearMonster{c,true}},0,4096);}
int main(){auto known=quote(2);yes(known.complete&&known.ready&&!known.uncertain,"known two-phase shield funds actual remaining clear");yes(known.ticks==3&&known.remaining_hp==std::vector<double>{300}&&known.damage_taken==std::vector<double>{0},"known carry protects exactly both future camp replies");yes(!quote(1).complete,"one remaining phase cannot cover second monster reply");yes(!quote(0).complete,"zero remaining duration supplies no future shield");yes(!quote(-1).complete,"unknown expiry supplies no future shield");yes(!quote(2,50).complete,"known duration cannot restore spent shield value");auto one=quote(1,50,100);yes(one.complete&&one.ticks==2&&one.remaining_hp==std::vector<double>{300},"duration1 covers next camp phase before champion expiry");auto long_shield=quote(5,250);yes(long_shield.complete&&long_shield.damage_taken==std::vector<double>{0},"unused longer native shield is retained within known lifetime");yes(!quote(2,std::numeric_limits<double>::infinity()).complete,"nonfinite observed shield supplies no safety credit");std::printf("%d camp shield clock checks passed\n",checks);}
